-- [1] 사전 확인 : 결과가 각각 1, 0, 0 이어야 진행
SELECT COUNT(*) AS QH_ROOT_CNT FROM TCOZ_MNU_INFO WHERE MNU_CD = 'QH';
SELECT COUNT(*) AS QH_CHILD_CNT FROM TCOZ_MNU_INFO WHERE MNU_CD LIKE 'QH_%';
SELECT COUNT(*) AS URL_DUP_CNT FROM TCOZ_MNU_INFO WHERE URL LIKE '/qha/%' OR URL LIKE '/qhb/%' OR URL LIKE '/qh/%';

