-- [4] 사후 검증
-- 4-1. 건수 : 135
SELECT COUNT(*) FROM TCOZ_MNU_INFO WHERE MNU_CD LIKE 'QH_%' AND IPT_ID = 'MIG_JH_QS';
-- 4-2. 계층 끊김 : 0
SELECT COUNT(*) FROM TCOZ_MNU_INFO C
 WHERE C.MNU_CD LIKE 'QH_%'
   AND NOT EXISTS (SELECT 1 FROM TCOZ_MNU_INFO P WHERE P.MNU_CD = C.HRNK_CD);
-- 4-3. 트리 조회 : 136 (root 포함)
SELECT COUNT(*) FROM TCOZ_MNU_INFO START WITH MNU_CD = 'QH' CONNECT BY PRIOR MNU_CD = HRNK_CD;
-- 4-4. URL 중복 : 0건
SELECT URL, COUNT(*) FROM TCOZ_MNU_INFO WHERE URL IS NOT NULL GROUP BY URL HAVING COUNT(*) > 1;
-- 4-5. QS 잔존 경로 : 0
SELECT COUNT(*) FROM TCOZ_MNU_INFO WHERE MNU_CD LIKE 'QH_%' AND (URL LIKE '/qs%' OR FILE_PATH LIKE '/qs/%');

